class D1Adapter{
 constructor(){this.sqlite=new DatabaseSync(':memory:');this.sqlite.exec(readFileSync(new URL('../migrations/0001_foundation.sql',import.meta.url),'utf8'));}
 prepare(sql){const db=this.sqlite;let args=[];return {bind(...values){args=values;return this},async all(){return {results:db.prepare(sql).all(...args)}},async first(){return db.prepare(sql).get(...args)||null},run(){return db.prepare(sql).run(...args)}};}
 async batch(statements){this.sqlite.exec('BEGIN');try{const result=statements.map(s=>s.run());this.sqlite.exec('COMMIT');return result;}catch(e){this.sqlite.exec('ROLLBACK');throw e;}}
}
const user={email:'admin@example.test',organizationId:'giolina-preview',role:'admin'};
function fixture(){const env={CRM_DB:new D1Adapter()};async function call(path,method='GET',body,userOverride=user,headers={}){const response=await api(new Request('https://preview.example.workers.dev/api/admin/'+path,{method,headers:{Origin:'https://preview.example.workers.dev','Content-Type':'application/json','X-GioLina-Request':'admin',...headers},...(body?{body:JSON.stringify(body)}:{})}),env,userOverride,path);return {status:response.status,data:await response.json()};}return {call,env};}
test('catalog preserves prices, hours, missing prices and historical variants',()=>{assert.equal(catalog.length,47);assert.equal(new Set(catalog.map(r=>r.id)).size,47);for(const row of catalog)assert.deepEqual(validate('services',Object.fromEntries(Object.entries(row).filter(([k])=>k!=='id'))),{...Object.fromEntries(Object.entries(row).filter(([k])=>k!=='id')),active:true});assert.equal(catalog.find(r=>r.category==='Wedding 2026'&&r.conflictGroup==='wedding-feature').priceCents,315000);assert.equal(catalog.find(r=>r.category==='Sweet Sixteen 2024'&&r.conflictGroup==='overtime').priceCents,12500);assert.equal(catalog.filter(r=>r.category.startsWith('Saved')).length,25);assert(catalog.filter(r=>r.conflictGroup==='additional-cinematographer').some(r=>r.coverageHours===10&&r.priceCents===null));});
test('CRUD, optimistic edits, organization isolation, seed idempotency and lead conversion',async()=>{const {call,env}=fixture();assert.equal((await call('seed','POST',{})).status,201);assert.equal((await call('seed','POST',{})).status,200);assert.equal((await call('services')).data.length,50);const contact=(await call('contacts','POST',{data:{name:'Demo contact',email:'demo@example.test',demo:true}})).data;assert(contact.id);assert.equal((await call('contacts/'+contact.id,'PUT',{data:{...contact,id:undefined},version:contact.version})).status,400);const updated=await call('contacts/'+contact.id,'PUT',{data:{name:'Updated demo',email:'demo@example.test',demo:true},version:1});assert.equal(updated.data.version,2);assert.equal((await call('contacts/'+contact.id,'PUT',{data:{name:'Stale',email:'demo@example.test'},version:1})).status,409);assert.deepEqual((await call('contacts','GET',null,{...user,organizationId:'other'})).data,[]);const lead=(await call('leads','POST',{data:{name:'Demo inquiry',contactId:contact.id,eventType:'Wedding',status:'New Inquiry',demo:true}})).data;assert.equal((await call('leads/'+lead.id+'/convert','POST',{version:1})).status,201);assert.equal((await call('leads/'+lead.id+'/convert','POST',{version:1})).status,409);assert.equal((await call('projects')).data.length,1);assert.equal(env.CRM_DB.sqlite.prepare('SELECT COUNT(*) n FROM write_guards').get().n,0);assert((await call('activity')).data.length>=4);});
test('atomic appointment overlaps, buffers, cancellation, rescheduling and blocked dates',async()=>{const {call}=fixture();const contact=(await call('contacts','POST',{data:{name:'Demo',email:'demo@example.test'}})).data;const type=(await call('appointment-types','POST',{data:{name:'Demo consultation',durationMinutes:30,bufferMinutes:10}})).data;const data={name:'Demo meeting',contactId:contact.id,appointmentTypeId:type.id,startAt:'2026-11-05T15:00:00Z',endAt:'2026-11-05T15:30:00Z',status:'Scheduled'};const first=(await call('appointments','POST',{data})).data;assert(first.id);assert.equal((await call('appointments','POST',{data:{...data,startAt:'2026-11-05T15:35:00Z',endAt:'2026-11-05T16:05:00Z'}})).status,409);assert.equal((await call('appointments')).data.length,1);assert.equal((await call('appointments/'+first.id,'PUT',{data:{...data,status:'Cancelled'},version:1})).status,200);assert.equal((await call('appointments','POST',{data})).status,201);await call('availability','POST',{data:{name:'Demo blocked date',dayOfWeek:'Friday',startTime:'09:00',endTime:'17:00',blockedDate:'2026-11-06'}});assert.equal((await call('appointments','POST',{data:{...data,startAt:'2026-11-06T15:00:00Z',endAt:'2026-11-06T15:30:00Z'}})).status,409);});
