test('JWT verifies signature, audience, issuer, expiry and exact administrator allowlist',async()=>{const {privateKey,publicKey}=await generateKeyPair('RS256');const jwk=await exportJWK(publicKey);jwk.kid='test';const keys=createLocalJWKSet({keys:[jwk]});const env={CRM_ACCESS_TEAM:'example.cloudflareaccess.com',CRM_ACCESS_AUD:'admin-audience',CRM_ADMIN_EMAILS:'admin@example.test'};async function token(email='admin@example.test',aud='admin-audience',expires='1h'){return new SignJWT({email}).setProtectedHeader({alg:'RS256',kid:'test'}).setIssuer('https://example.cloudflareaccess.com').setAudience(aud).setSubject('example-subject').setIssuedAt().setExpirationTime(expires).sign(privateKey)}assert.equal((await verifyIdentity(await token(),env,keys)).role,'admin');assert.equal(await verifyIdentity(await token('other@example.test'),env,keys),null);await assert.rejects(verifyIdentity(await token('admin@example.test','wrong'),env,keys));await assert.rejects(verifyIdentity(await token('admin@example.test','admin-audience','-1h'),env,keys));await assert.rejects(verifyIdentity((await token()).slice(0,-3)+'bad',env,keys));assert.equal(await authenticate(new Request('https://giolinafilms.com/admin/'),{...env,CRM_STAGE:'preview',CRM_ORIGIN:'https://example.workers.dev'}),null);});
test('all private resources fail closed; public site and non-GET behavior remain intact',async()=>{for(const path of ['/admin/','/admin/contacts/','/admin/app.js','/admin/app.css','/api/admin/meta','/api/admin/services','/portal/','/api/portal/projects']){const response=await handlePrivate(new Request('https://example.workers.dev'+path),{});assert([401,503].includes(response.status));assert.equal(response.headers.get('Cache-Control'),'no-store');const body=await response.text();assert(!body.includes('Imported 47'));assert(!body.includes('5-Hour Corporate'));assert(!body.includes('record-form'));}let called=0;const env={ASSETS:{async fetch(){called++;return new Response('public content')}}};const publicResponse=await worker.fetch(new Request('https://example.workers.dev/'),env);assert.equal(await publicResponse.text(),'public content');assert.equal(called,1);assert.equal((await worker.fetch(new Request('https://example.workers.dev/',{method:'POST'}),env)).status,405);assert.equal((await worker.fetch(new Request('https://example.workers.dev/admin/',{headers:{'Cf-Access-Authenticated-User-Email':'admin@example.test'}}),env)).status,503);});
test('large service imports and appointments use bounded query counts',async()=>{const {call,env}=fixture();const original=env.CRM_DB.prepare.bind(env.CRM_DB);let queries=0;env.CRM_DB.prepare=sql=>{queries++;return original(sql)};await call('seed','POST',{});assert(queries<10,'Catalog import should not query once per service');const contact=(await call('contacts','POST',{data:{name:'Demo',email:'demo@example.test'}})).data;const type=(await call('appointment-types','POST',{data:{name:'Long demo meeting',durationMinutes:480,bufferMinutes:240}})).data;queries=0;const saved=await call('appointments','POST',{data:{name:'Large appointment',contactId:contact.id,appointmentTypeId:type.id,startAt:'2026-11-10T13:00:00Z',endAt:'2026-11-10T21:00:00Z'}});assert.equal(saved.status,201);assert(queries<20,'Reservation should not query once per minute');assert.equal(env.CRM_DB.sqlite.prepare('SELECT COUNT(*) n FROM appointment_locks').get().n,960);});

