test('project-home portal includes contract drafts, keeps resend access and explicitly refreshes snapshots',async()=>{
 const {call,env}=fixture();Object.assign(env,{CRM_STAGE:'preview',CRM_ORIGIN:'https://preview.example.workers.dev'});const contact=(await call('contacts','POST',{data:{name:'DEMO Project Home',email:'home@example.test',demo:true}})).data,project=(await call('projects','POST',{data:{name:'DEMO Project Home',contactId:contact.id,eventType:'Wedding',venue:'DEMO venue',location:'DEMO location',status:'Inquiry',demo:true,notes:'PRIVATE NOTE'}})).data;const route='projects/'+project.id+'/portal-access';await call(route,'POST',{action:'invite',version:0});let active=(await call(route,'POST',{action:'activate-demo',version:1})).data;let html=await(await worker.fetch(new Request(active.url),env)).text();for(const id of ['overview','documents','schedule','payments','files'])assert(html.includes('id="'+id+'"'));assert(html.includes('DEMO location'));assert(!html.includes('PRIVATE NOTE'));const contractData={name:'DEMO contract',projectId:project.id,body:'DEMO draft for {{clientName}}',status:'Draft',notes:'PRIVATE CONTRACT NOTE'};const contract=(await call('contracts','POST',{data:contractData})).data;assert.equal((await worker.fetch(new Request(active.url+'/contract/'+contract.id),env)).status,404);let info=(await call(route)).data;const resent=await call(route,'POST',{action:'resend',version:info.version});assert.equal(resent.data.status,'Active');assert.equal(resent.data.url,active.url);info=(await call(route)).data;assert.equal((await call(route,'POST',{action:'refresh-documents',version:info.version})).status,200);const contractUrl=active.url+'/contract/'+contract.id;const preview=await worker.fetch(new Request(contractUrl),env);assert.equal(preview.status,200);html=await preview.text();assert(html.includes('DEMO draft for DEMO Project Home'));assert(!html.includes('PRIVATE CONTRACT NOTE'));assert(html.includes('Back to your event'));assert.equal((await worker.fetch(new Request(contractUrl+'/pdf'),env)).headers.get('Content-Type'),'application/pdf');await call('contracts/'+contract.id,'PUT',{version:1,data:{...contractData,body:'Updated DEMO draft'}});assert((await(await worker.fetch(new Request(contractUrl),env)).text()).includes('DEMO draft for'));const current=(await call(route)).data;await call(route,'POST',{action:'disable',version:current.version});assert.equal((await worker.fetch(new Request(contractUrl),env)).status,404);assert.equal((await call(route,'POST',{action:'refresh-documents',version:current.version+1})).status,409);
});

test('tasks persist status, trusted completion time, project identity, reopen and organization isolation',async()=>{
 const {call}=fixture();const contact=(await call('contacts','POST',{data:{name:'DEMO Task Client',email:'task@example.test',demo:true}})).data,other=(await call('contacts','POST',{data:{name:'Other',email:'other@example.test',demo:true}})).data,project=(await call('projects','POST',{data:{name:'DEMO Task Project',contactId:contact.id,eventType:'Wedding',status:'Inquiry',demo:true}})).data;
 const create=await call('tasks','POST',{data:{name:'Call client',projectId:project.id,status:'TO DO',priority:'High',dueAt:'2027-01-10',notes:'Demo only'}});assert.equal(create.status,201);const row=create.data;assert.equal(row.contactId,contact.id);assert.equal(row.demo,true);assert.equal(row.completed,false);assert.equal(row.completedAt,null);
 const data={name:row.name,projectId:project.id,status:'IN PROGRESS',priority:'High',dueAt:row.dueAt};let saved=await call('tasks/'+row.id,'PUT',{version:row.version,data});assert.equal(saved.status,200);assert.equal(saved.data.completed,false);
 saved=await call('tasks/'+row.id,'PUT',{version:saved.data.version,data:{...data,status:'DONE'}});assert.equal(saved.data.completed,true);assert(Number.isFinite(Date.parse(saved.data.completedAt)));const timestamp=saved.data.completedAt;
 const again=await call('tasks/'+row.id,'PUT',{version:saved.data.version,data:{...data,status:'DONE',notes:'Done note'}});assert.equal(again.data.completedAt,timestamp);
 const history=(await call('activity?project='+project.id)).data;assert.equal(history.filter(a=>a.action==='task-completed').length,1);
 saved=await call('tasks/'+row.id,'PUT',{version:again.data.version,data:{...data,status:'TO DO'}});assert.equal(saved.data.completedAt,null);assert.equal(saved.data.completed,false);
 assert.equal((await call('tasks/'+row.id,'PUT',{version:1,data})).status,409);assert.equal((await call('tasks','POST',{data:{...data,contactId:other.id}})).status,400);assert.equal((await call('tasks','POST',{data:{...data,status:'Fake'}})).status,400);assert.equal((await call('tasks','POST',{data:{...data,completedAt:'2020-01-01'}})).status,400);
 assert.deepEqual((await call('tasks','GET',null,{...user,organizationId:'other-org'})).data,[]);
 saved=await call('tasks/'+row.id,'PUT',{version:saved.data.version,data:{...data,archived:true}});assert.equal(saved.data.archived,true);
});

